861: /* decode 4 sixpack-encoded bytes into 3 data bytes */
862: 
863: static void decode_data(struct sixpack *sp, unsigned char inbyte)
864: {
865: 	unsigned char *buf;
866: 
867: 	if (sp->rx_count != 3) {
868: 		sp->raw_buf[sp->rx_count++] = inbyte;
869: 
870: 		return;
871: 	}
872: 
873: 	if (sp->rx_count_cooked + 2 >= sizeof(sp->cooked_buf)) {
874: 		pr_err("6pack: cooked buffer overrun, data loss\n");
875: 		sp->rx_count = 0;
876: 		return;
877: 	}
878: 
879: 	buf = sp->raw_buf;
880: 	sp->cooked_buf[sp->rx_count_cooked++] =
881: 		buf[0] | ((buf[1] << 2) & 0xc0);
882: 	sp->cooked_buf[sp->rx_count_cooked++] =
883: 		(buf[1] & 0x0f) | ((buf[2] << 2) & 0xf0);
884: 	sp->cooked_buf[sp->rx_count_cooked++] =
885: 		(buf[2] & 0x03) | (inbyte << 2);
886: 	sp->rx_count = 0;
887: }
